import factory = require( './index' );

/**
* TESTS
*/

// The factory function returns a function...
{
	const rng = factory();
	rng(); // $ExpectType number
	rng.normalized(); // $ExpectType number
	rng.copy(); // $ExpectType () => number
}

// The factory function accepts a seed option...
{
	const rng = factory( {
		'seed': 1234
	});
	rng(); // $ExpectType number
}

// The factory function accepts a state option...
{
	const state = new Uint32Array( 4 );
	const rng = factory( {
		'state': state
	});
	rng(); // $ExpectType number
}

// The factory function accepts both seed and state options...
{
	const state = new Uint32Array( 4 );
	const rng = factory( {
		'seed': 1234,
		'state': state
	});
	rng(); // $ExpectType number
}

// The factory function accepts a copy option...
{
	const rng = factory( {
		'copy': true
	});
	rng(); // $ExpectType number
}

// The factory function returns an object with NAME property...
{
	const rng = factory();
	rng.NAME; // $ExpectType string
}

// The factory function returns an object with seed property...
{
	const rng = factory();
	rng.seed; // $ExpectType number
}

// The factory function returns an object with state property (getter)...
{
	const rng = factory();
	rng.state; // $ExpectType Uint32Array
}

// The factory function returns an object with state property (setter)...
{
	const rng = factory();
	const state = new Uint32Array( 4 );
	rng.state = state;
}

// The factory function returns an object with toJSON method...
{
	const rng = factory();
	rng.toJSON(); // $ExpectType { type: string; name: string; state: Uint32Array; params: unknown[]; }
}

// The factory function returns an object with copy method...
{
	const rng = factory();
	rng.copy(); // $ExpectType () => number
}

// The factory function returns an object with normalized method...
{
	const rng = factory();
	rng.normalized(); // $ExpectType number
}

// Test that factory can be called with options parameter...
{
	const rng = factory( {
		'seed': 12345,
		'copy': false
	});
	rng(); // $ExpectType number
	rng.normalized(); // $ExpectType number
	rng.copy(); // $ExpectType () => number
}

// Test that state array must be Uint32Array...
{
	const rng1 = factory();
	const state = rng1.state;
	const rng2 = factory( {
		'state': state
	});
	rng2(); // $ExpectType number
}

// Test that seed must be a number...
{
	const rng = factory( {
		'seed': 999
	});
	rng(); // $ExpectType number
}

// Test getting and setting state...
{
	const rng1 = factory( {
		'seed': 42
	});
	
	// Generate some values
	rng1();
	rng1();
	
	// Get state
	const state = rng1.state;
	state; // $ExpectType Uint32Array
	
	// Create new PRNG with saved state
	const rng2 = factory( {
		'state': state
	});
	
	// Should continue from same state
	rng2(); // $ExpectType number
}

// Test copy functionality...
{
	const rng1 = factory( {
		'seed': 100
	});
	
	const rng2 = rng1.copy();
	
	const v1 = rng1();
	const v2 = rng2();
	
	v1; // $ExpectType number
	v2; // $ExpectType number
}

// Test normalized output...
{
	const rng = factory( {
		'seed': 555
	});
	
	const normalized = rng.normalized();
	normalized; // $ExpectType number
	
	// Should be in [0, 1)
	if ( normalized >= 0 && normalized < 1 ) {
		// valid
	}
}

// Test toJSON serialization...
{
	const rng = factory( {
		'seed': 777
	});
	
	const json = rng.toJSON();
	json.type; // $ExpectType string
	json.name; // $ExpectType string
	json.state; // $ExpectType Uint32Array
	json.params; // $ExpectType unknown[]
}

// Test NAME constant...
{
	const rng = factory();
	if ( rng.NAME === 'xorshift128+' ) {
		// Expected
	}
}

// Test seed property...
{
	const rng = factory( {
		'seed': 1234
	});
	
	const seed = rng.seed;
	seed; // $ExpectType number
}

// Test consecutive generation...
{
	const rng = factory( {
		'seed': 2000
	});
	
	const v1 = rng();
	const v2 = rng();
	const v3 = rng();
	
	v1; // $ExpectType number
	v2; // $ExpectType number
	v3; // $ExpectType number
}
